import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Tiled direct 2D convolution (NCHW, contiguous, float32).
// Each CTA computes a 16x16 output tile for one (batch, out_channel) pair.
// The required input tile (halo included) for each input channel is staged
// into shared memory cooperatively, then reused by all 256 threads.
.extern .shared .align 4 .b8 smem[];
.visible .entry conv2d_kernel(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 has_bias,
    .param .u32 OC,
    .param .u32 OH,
    .param .u32 OW,
    .param .u32 IC,
    .param .u32 H,
    .param .u32 W,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 in_tile_h,
    .param .u32 in_tile_w
)
{
    .reg .pred %p<16>;
    .reg .b32  %r<64>;
    .reg .b64  %rd<24>;
    .reg .f32  %f<8>;
    mov.u32 %r40, 16;                       // TILE
    mov.u32 %r41, 256;                      // blockDim.x
    mov.u32 %r0, %tid.x;                    // tid
    div.u32 %r1, %r0, %r40;                 // th = tid / 16
    rem.u32 %r2, %r0, %r40;                 // tw = tid % 16
    mov.u32 %r3, %ctaid.x;                  // tile column
    mov.u32 %r4, %ctaid.y;                  // tile row
    mov.u32 %r5, %ctaid.z;                  // b*OC + oc
    ld.param.u32 %r6, [OC];
    rem.u32 %r7, %r5, %r6;                  // oc
    div.u32 %r8, %r5, %r6;                  // b
    ld.param.u32 %r9, [OH];
    ld.param.u32 %r10, [OW];
    mad.lo.u32 %r11, %r4, %r40, %r1;        // oh
    mad.lo.u32 %r12, %r3, %r40, %r2;        // ow
    setp.lt.u32 %p0, %r11, %r9;
    setp.lt.u32 %p1, %r12, %r10;
    and.pred  %p2, %p0, %p1;                // output valid
    ld.param.u32 %r13, [stride_h];
    ld.param.u32 %r14, [stride_w];
    ld.param.u32 %r15, [pad_h];
    ld.param.u32 %r16, [pad_w];
    // ih0 = tile_row*16*stride_h - pad_h  (signed)
    mul.lo.u32 %r17, %r4, %r40;
    mul.lo.u32 %r17, %r17, %r13;
    sub.s32    %r17, %r17, %r15;
    // iw0 = tile_col*16*stride_w - pad_w  (signed)
    mul.lo.u32 %r18, %r3, %r40;
    mul.lo.u32 %r18, %r18, %r14;
    sub.s32    %r18, %r18, %r16;
    ld.param.u32 %r19, [IC];
    ld.param.u32 %r20, [H];
    ld.param.u32 %r21, [W];
    ld.param.u32 %r22, [KH];
    ld.param.u32 %r23, [KW];
    ld.param.u32 %r24, [dil_h];
    ld.param.u32 %r25, [dil_w];
    ld.param.u32 %r26, [in_tile_h];
    ld.param.u32 %r27, [in_tile_w];
    mul.lo.u32 %r28, %r26, %r27;            // tile_size
    mov.u64 %rd0, smem;                     // shared tile base
    mov.f32 %f0, 0f00000000;                // acc = 0.0f
    mov.u32 %r29, 0;                        // ic = 0
LOOP_IC:
    setp.ge.u32 %p3, %r29, %r19;
    @%p3 bra STORE;
    // Cooperative load of the input tile for channel ic (zero fill OOB).
    mov.u32 %r30, %r0;                      // idx = tid
LOAD_LOOP:
    setp.ge.u32 %p4, %r30, %r28;
    @%p4 bra LOAD_DONE;
    div.u32 %r31, %r30, %r27;               // ith
    rem.u32 %r32, %r30, %r27;               // itw
    add.s32 %r33, %r17, %r31;               // ih
    add.s32 %r34, %r18, %r32;               // iw
    mov.f32 %f1, 0f00000000;
    setp.lt.s32 %p5, %r33, 0;
    setp.ge.s32 %p6, %r33, %r20;
    or.pred  %p7, %p5, %p6;
    setp.lt.s32 %p8, %r34, 0;
    or.pred  %p7, %p7, %p8;
    setp.ge.s32 %p9, %r34, %r21;
    or.pred  %p7, %p7, %p9;
    @%p7 bra WRITE_SMEM;
    // input index = ((b*IC + ic)*H + ih)*W + iw
    mad.lo.u32 %r35, %r8, %r19, %r29;
    mad.lo.u32 %r35, %r35, %r20, %r33;
    mad.lo.u32 %r35, %r35, %r21, %r34;
    cvt.u64.u32 %rd1, %r35;
    shl.b64     %rd1, %rd1, 2;
    ld.param.u64 %rd2, [in_ptr];
    add.u64     %rd2, %rd2, %rd1;
    ld.global.f32 %f1, [%rd2];
WRITE_SMEM:
    cvt.u64.u32 %rd3, %r30;
    shl.b64     %rd3, %rd3, 2;
    add.u64     %rd4, %rd0, %rd3;
    st.shared.f32 [%rd4], %f1;
    add.u32 %r30, %r30, %r41;
    bra LOAD_LOOP;
LOAD_DONE:
    bar.sync 0;
    @!%p2 bra AFTER_COMPUTE;                // invalid outputs skip compute
    // Accumulate over (kh, kw) from the staged shared-memory tile.
    mov.u32 %r36, 0;                        // kh
LOOP_KH:
    setp.ge.u32 %p10, %r36, %r22;
    @%p10 bra COMPUTE_DONE;
    // ih_l = th*stride_h + kh*dil_h
    mul.lo.u32 %r37, %r1, %r13;
    mad.lo.u32 %r37, %r36, %r24, %r37;
    mov.u32 %r38, 0;                        // kw
LOOP_KW:
    setp.ge.u32 %p11, %r38, %r23;
    @%p11 bra NEXT_KH;
    // iw_l = tw*stride_w + kw*dil_w
    mul.lo.u32 %r39, %r2, %r14;
    mad.lo.u32 %r39, %r38, %r25, %r39;
    // smem idx = ih_l*in_tile_w + iw_l
    mad.lo.u32 %r42, %r37, %r27, %r39;
    cvt.u64.u32 %rd5, %r42;
    shl.b64     %rd5, %rd5, 2;
    add.u64     %rd6, %rd0, %rd5;
    ld.shared.f32 %f2, [%rd6];
    // weight index = ((oc*IC + ic)*KH + kh)*KW + kw
    mad.lo.u32 %r43, %r7, %r19, %r29;
    mad.lo.u32 %r43, %r43, %r22, %r36;
    mad.lo.u32 %r43, %r43, %r23, %r38;
    cvt.u64.u32 %rd7, %r43;
    shl.b64     %rd7, %rd7, 2;
    ld.param.u64 %rd8, [wt_ptr];
    add.u64     %rd9, %rd8, %rd7;
    ld.global.f32 %f3, [%rd9];
    fma.rn.f32 %f0, %f2, %f3, %f0;
    add.u32 %r38, %r38, 1;
    bra LOOP_KW;
NEXT_KH:
    add.u32 %r36, %r36, 1;
    bra LOOP_KH;
COMPUTE_DONE:
AFTER_COMPUTE:
    bar.sync 0;                             // tile fully consumed
    add.u32 %r29, %r29, 1;
    bra LOOP_IC;
STORE:
    @!%p2 bra DONE;
    ld.param.u32 %r44, [has_bias];
    setp.eq.u32  %p12, %r44, 0;
    @%p12 bra WRITE;
    cvt.u64.u32 %rd10, %r7;                 // oc
    shl.b64     %rd10, %rd10, 2;
    ld.param.u64 %rd11, [bias_ptr];
    add.u64     %rd12, %rd11, %rd10;
    ld.global.f32 %f4, [%rd12];
    add.f32     %f0, %f0, %f4;
WRITE:
    // out index = ((b*OC + oc)*OH + oh)*OW + ow
    mad.lo.u32 %r45, %r8, %r6, %r7;
    mad.lo.u32 %r45, %r45, %r9, %r11;
    mad.lo.u32 %r45, %r45, %r10, %r12;
    cvt.u64.u32 %rd13, %r45;
    shl.b64     %rd13, %rd13, 2;
    ld.param.u64 %rd14, [out_ptr];
    add.u64     %rd15, %rd14, %rd13;
    st.global.f32 [%rd15], %f0;
DONE:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
